package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.village.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes;
public final class VillageDefenseEventGameTest{@GameTest public void golemDeathCreatesVillageEvent(GameTestHelper c){c.spawn(EntityTypes.VILLAGER,2,1,2);var g=c.spawn(EntityTypes.IRON_GOLEM,3,1,2);c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());var id=VillageManager.get(c.getLevel().getServer()).all().iterator().next().villageId();g.kill();c.runAtTickTime(2,()->{if(VillageEventManager.get(c.getLevel().getServer()).get(id).stream().noneMatch(e->e.type().equals("golem_died"))){c.fail("Golem death was not recorded");return;}c.succeed();});});}}
